function tipAmount(bill, pct){ return bill*pct/100; }
function total(bill, pct){ return bill + tipAmount(bill, pct); }
function perPerson(bill, pct, party){ if(!party) return NaN; return total(bill, pct)/party; }
function roundUpDollar(t){ return Math.ceil(t); }
var EXPORTS = { tipAmount:tipAmount, total:total, perPerson:perPerson, roundUpDollar:roundUpDollar };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TipForgePure = EXPORTS; }
